(function(){'use strict';
/* JAH The Spectroscopy Signature generator — jahdb-spectroscopy-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-SPECCS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Spectroscopy", "desc": "Spectroscopy studies how matter interacts with electromagnetic radiation: absorbing, emitting, or scattering photons. Each interaction encodes structure - the sodium D lines fingerprint sodium, an IR spectrum fingerprints functional groups, an NMR spectrum maps a molecule atom by atom.\nIt is chemistry's primary identification tool and physics' probe of quantum structure. From Fraunhofer's solar lines (1814) to attosecond pulses, spectroscopy has repeatedly rewritten what we know about atoms, molecules, and the universe.", "how": "Choose the spectral region for the question: electronic (UV-vis), vibrational (IR/Raman), rotational (microwave), nuclear spin (NMR), inner-shell (X-ray). Match photon energy to the transition energy (E = hν). Interpret with selection rules; quantify with Beer-Lambert.", "keys": ["Light-matter interaction reveals structure.", "Absorption, emission, scattering: three signals.", "Photon energy matched to transition energy.", "Chemistry's primary identification tool.", "From Fraunhofer lines to attosecond pulses."], "reqs": ["Spectral region matched to transition.", "Calibrated wavelength/frequency axis.", "Selection-rule analysis."], "stds": ["Wavelength/frequency with units.", "Spectra reported with conditions."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Region picker by transition type.\"\"\"\ntable = {\"electronic\": \"UV-vis\", \"vibrational\": \"infrared\", \"rotational\": \"microwave\", \"nuclear spin\": \"radio (NMR)\", \"core electron\": \"X-ray\"}\nfor trans, region in table.items():\n    print(f\"  {trans:14s} -> {region}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Electromagnetic Spectrum", "desc": "From gamma rays (10⁻¹² m) to radio waves (10³ m): the spectrum spans 15 orders of magnitude. Spectroscopy's regions - X-ray, UV, visible, IR, microwave, radio - each probe different energies: core electrons, valence electrons, vibrations, rotations, nuclear spins.\nThe visible band (380-750 nm) is a sliver our eyes evolved to see; instruments see it all. Astronomers read the universe in every band - radio maps hydrogen, X-rays map black holes.", "how": "Convert fluently: E = hc/λ, ν̄ = 1/λ, E(eV) = 1240/λ(nm). Assign regions to transitions by energy matching. Remember atmospheric windows (what reaches the ground) for observational work.", "keys": ["15 orders of magnitude, one spectrum.", "Each region probes different energies.", "Visible light is a sliver of the whole.", "E = hc/λ converts wavelength to energy.", "Astronomy reads every band."], "reqs": ["Wavelength/frequency/energy with units.", "Region-transition matching.", "Atmospheric transmission for ground work."], "stds": ["SI units; eV for photon energies.", "1240/λ(nm) = eV conversion."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Banwell CN, McCash EM. Fundamentals of Molecular Spectroscopy. 4th ed. McGraw-Hill; 1994."], "demo": "#!/usr/bin/env python3\n\"\"\"Photon energy across the spectrum.\"\"\"\ndef eV(lam_m):\n    return 6.626e-34*3e8/lam_m/1.602e-19\nfor name, lam in [(\"X-ray\", 1e-10), (\"UV\", 3e-7), (\"visible\", 5e-7), (\"IR\", 1e-5), (\"microwave\", 1e-2)]:\n    print(f\"  {name:9s}: {eV(lam):.2e} eV\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Light-Matter Interaction Basics", "desc": "Photons interact by absorption (molecule takes the photon, jumps up), spontaneous/stimulated emission (molecule drops, emits), and scattering (photon redirects, Rayleigh elastic or Raman inelastic). Einstein's A and B coefficients (1917) quantify emission and absorption - the basis of lasers.\nResonance is required: the photon energy must match the transition gap (ΔE = hν). Off-resonance light passes through - why glass is transparent to visible light but opaque to UV.", "how": "Check resonance: photon energy vs transition gap. Classify the process (absorption/emission/scattering) from the experimental geometry. Use Einstein coefficients for rate predictions; design lasers around stimulated emission with population inversion.", "keys": ["Absorption, emission, scattering: three interactions.", "Resonance required: ΔE = hν.", "Einstein A/B coefficients quantify rates.", "Stimulated emission enables lasers.", "Transparency = no resonant transitions."], "reqs": ["Photon energy vs gap comparison.", "Interaction geometry.", "Population/level diagram."], "stds": ["Einstein coefficients in s⁻¹.", "Cross-sections in cm²."], "cites": ["Einstein A. Phys Z 1917;18:121-128.", "Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Resonance check: photon vs transition.\"\"\"\ndef resonant(E_photon_eV, E_gap_eV, tol=0.05):\n    return abs(E_photon_eV-E_gap_eV) < tol\nprint(\"  2.0 eV photon vs 2.0 eV gap:\", resonant(2.0, 2.0))\nprint(\"  2.0 eV photon vs 5.0 eV gap:\", resonant(2.0, 5.0))\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Absorption, Emission, and Scattering", "desc": "Absorption spectra show what a sample takes: UV-vis absorption of dyes, IR absorption of bonds. Emission spectra show what it gives back: flame colors, fluorescence, phosphorescence - often more sensitive since signal appears against darkness.\nScattering redirects photons: Rayleigh (elastic, blue sky - λ⁻⁴), Raman (inelastic, energy shifted by vibrations - the Raman spectrum), Tyndall (colloids). Each carries different information; together they are the complete optical toolkit.", "how": "Choose absorption for concentration (Beer-Lambert), emission for sensitivity (trace analysis), scattering for structure/dynamics (Raman, DLS). Remember Kasha's rule: emission comes from the lowest excited state regardless of excitation wavelength.", "keys": ["Absorption quantifies; emission sensitizes.", "Rayleigh: elastic (sky blue); Raman: inelastic (vibrations).", "Emission against darkness = high sensitivity.", "Kasha: emission from lowest excited state.", "Three signals, complementary information."], "reqs": ["Geometry (transmission vs 90° vs backscatter).", "Excitation wavelength.", "Dark background for emission."], "stds": ["Spectra corrected for instrument response.", "Quantum yields where relevant."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Lakowicz JR. Principles of Fluorescence Spectroscopy. 3rd ed. Springer; 2006."], "demo": "#!/usr/bin/env python3\n\"\"\"Rayleigh λ⁻⁴: why the sky is blue.\"\"\"\ndef scatter(lam_nm):\n    return (550/lam_nm)**4\nfor lam in (450, 550, 650):\n    print(f\"  {lam} nm: relative scattering {scatter(lam):.2f}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Wavelength, Frequency, Energy Relations", "desc": "c = λν ties wavelength to frequency; E = hν = hc/λ ties both to energy; ν̄ = 1/λ (wavenumbers, cm⁻¹) is the spectroscopist's energy unit - directly proportional to E. Fluency in conversion is the field's arithmetic.\nMnemonics: 1240/λ(nm) = eV; 1 eV = 8066 cm⁻¹ = 96.5 kJ/mol; room-temperature kT ≈ 207 cm⁻¹. These numbers let you judge instantly whether a transition is thermally accessible.", "how": "Convert with E = hc/λ; use wavenumbers for vibrational spectra (proportional to energy); use eV or nm for electronic. Compare gaps to kT (207 cm⁻¹ at 298 K) to judge thermal population - if ΔE >> kT, the upper state is empty.", "keys": ["c = λν; E = hν = hc/λ.", "Wavenumbers (cm⁻¹) are proportional to energy.", "1240/λ(nm) = eV; 1 eV = 8066 cm⁻¹.", "kT ≈ 207 cm⁻¹ at room temperature.", "ΔE >> kT means empty upper state."], "reqs": ["Consistent unit system.", "Conversion factors stated.", "Temperature for kT comparisons."], "stds": ["Wavenumbers in cm⁻¹ for vibrations.", "eV or nm for electronic transitions."], "cites": ["Banwell CN, McCash EM. Fundamentals of Molecular Spectroscopy. 4th ed. McGraw-Hill; 1994.", "Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Unit conversions for a 500 nm photon.\"\"\"\nlam_nm = 500\neV = 1240/lam_nm\nwn = eV*8066\nprint(f\"  {lam_nm} nm = {eV:.2f} eV = {wn:.0f} cm⁻¹ = {eV*96.5:.1f} kJ/mol\")\n"}, {"tier": "Foundations", "g": "Instruments", "title": "Spectrometers: How Instruments Work", "desc": "Every spectrometer has a source (tunable light), wavelength selector (monochromator, interferometer, or filter), sample holder, detector, and readout. Dispersive instruments scan wavelengths sequentially; Fourier-transform and diode-array instruments multiplex - measuring all wavelengths at once (Fellgett advantage).\nDetectors: photomultiplier tubes (UV-vis, single photon), CCD/CMOS arrays (multichannel), bolometers/DTGS (IR), photodiodes. Resolution vs throughput is the eternal trade-off (slit width).", "how": "Match components to the region: deuterium/tungsten + PMT for UV-vis; globar + DTGS/MCT for IR. Choose multiplex (FT/array) for speed and S/N. Set resolution to the problem - no finer than needed (throughput costs). Calibrate wavelength with standard lines.", "keys": ["Source, selector, sample, detector, readout.", "Multiplex (FT/array) beats scanning in speed.", "PMT: UV-vis; MCT: IR; CCD: multichannel.", "Resolution vs throughput trade-off.", "Calibrate with standard lines."], "reqs": ["Component specs per region.", "Resolution requirement.", "Wavelength calibration."], "stds": ["Resolution in nm or cm⁻¹.", "Calibration traceability."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Ingle JD, Crouch SR. Spectrochemical Analysis. Prentice Hall; 1988."], "demo": "#!/usr/bin/env python3\n\"\"\"Grating equation: resolvable wavelengths.\"\"\"\ndef dlambda(lam_nm, N_lines, order=1):\n    return lam_nm/(order*N_lines)\nprint(f\"  1200 lines/mm, 500 nm: Δλ = {dlambda(500, 1200*50):.3f} nm (5 cm grating)\")\n"}, {"tier": "Foundations", "g": "Quantitative", "title": "Beer-Lambert Law", "desc": "A = εbc: absorbance equals molar absorptivity × path × concentration. It is the quantitative core of absorption spectroscopy - from clinical assays to atmospheric monitoring. Transmittance T = I/I₀; A = -log₁₀T.\nLimits: high A (stray light), polychromatic radiation, and chemical changes with concentration (association, ionization shifts) all break linearity. The law holds per species - mixtures add absorbances (multi-component analysis).", "how": "Work at λmax in the linear range (A 0.1-1.0). Calibrate with standards; verify linearity. For mixtures, measure at n wavelengths for n components and solve the linear system. Correct baselines; use matched cuvettes.", "keys": ["A = εbc; A = -log10(T).", "Linear range ~0.1-1.0 absorbance.", "Deviations: stray light, polychromatic, chemistry.", "Mixtures: absorbances add.", "The quantitative core of absorption spectroscopy."], "reqs": ["λmax and linear range.", "Matched cuvettes, blank.", "Calibration standards."], "stds": ["ε in M⁻¹cm⁻¹.", "Path length in cm."], "cites": ["Beer A. Ann Phys 1852;86:78-88.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Concentration from absorbance.\"\"\"\ndef conc(A, eps, b=1.0):\n    return A/(eps*b)\nprint(f\"  A=0.434, eps=1.0e4: c = {conc(0.434, 1e4):.2e} M\")\n"}, {"tier": "Foundations", "g": "Theory", "title": "Spectral Lines and Broadening", "desc": "Lines have width: natural broadening (Heisenberg - short-lived states are broad), Doppler broadening (thermal motion - Gaussian profile), collisional/pressure broadening (Lorentzian), and instrumental broadening. Real lineshapes are Voigt (convolution).\nWidth carries information: Doppler widths give temperatures (astrophysics, plasmas); pressure broadening gives collision rates; natural widths give lifetimes. Narrow lines (Mössbauer, lasers) enable precision measurement.", "how": "Identify the dominant broadening: low pressure → Doppler; high pressure → collisional. Fit Voigt profiles to extract both. Use Doppler widths for remote thermometry; natural widths for excited-state lifetimes (ΔE·Δt ~ ħ).", "keys": ["Natural, Doppler, collisional, instrumental broadening.", "Doppler: Gaussian; collisional: Lorentzian; real: Voigt.", "Width encodes temperature, pressure, lifetime.", "Narrow lines enable precision (Mössbauer, lasers).", "Fit lineshapes to extract physics."], "reqs": ["Temperature and pressure.", "Instrumental resolution.", "Lineshape model."], "stds": ["Widths as FWHM with units.", "Voigt fits where mixed."], "cites": ["Banwell CN, McCash EM. Fundamentals of Molecular Spectroscopy. 4th ed. McGraw-Hill; 1994.", "Demtröder W. Laser Spectroscopy. 5th ed. Springer; 2014."], "demo": "#!/usr/bin/env python3\n\"\"\"Doppler width vs temperature.\"\"\"\ndef doppler_fwhm(T, M_kg_mol, nu0=1e14):\n    import math\n    return nu0*math.sqrt(8*8.314*T*math.log(2)/(M_kg_mol*9e16))\nfor T in (300, 3000):\n    print(f\"  T={T} K: Δν/ν = {doppler_fwhm(T, 0.028)/1e14:.2e}\")\n"}, {"tier": "Foundations", "g": "Theory", "title": "Selection Rules (Introduction)", "desc": "Not all transitions occur: selection rules from quantum mechanics (Δl = ±1 for electronic, Δv = ±1 for harmonic vibrations, ΔJ = ±1 for rotations) say which are allowed. Forbidden transitions are weak, not impossible - they proceed by higher-order mechanisms.\nGross selection rules are molecular: IR needs a changing dipole moment (heteronuclear diatomics active, O2/N2 silent); Raman needs changing polarizability (O2/N2 active). Mutual exclusion: centrosymmetric molecules split IR/Raman activity.", "how": "Apply Δ rules to predict allowed transitions. Use gross rules to predict IR vs Raman activity from symmetry. For centrosymmetric molecules, assign bands by mutual exclusion (no band in both). Remember: forbidden means weak, and overtones (Δv = ±2) appear weakly.", "keys": ["Δl=±1, Δv=±1, ΔJ=±1: the basic rules.", "IR: changing dipole; Raman: changing polarizability.", "Mutual exclusion in centrosymmetric molecules.", "Forbidden = weak, not absent.", "Overtones appear weakly."], "reqs": ["Quantum numbers of states.", "Molecular symmetry.", "Dipole/polarizability change."], "stds": ["Selection rules stated per transition type.", "Symmetry labels where used."], "cites": ["Banwell CN, McCash EM. Fundamentals of Molecular Spectroscopy. 4th ed. McGraw-Hill; 1994.", "Atkins P, de Paula J. Physical Chemistry. 11th ed. Oxford; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"IR vs Raman activity predictor.\"\"\"\ndef activity(mol):\n    table = {\"HCl\": (\"active\", \"active\"), \"O2\": (\"silent\", \"active\"), \"CO2\": (\"active\", \"active\"), \"H2O\": (\"active\", \"active\")}\n    return table.get(mol, (\"?\", \"?\"))\nfor m in (\"HCl\", \"O2\", \"CO2\"):\n    ir, raman = activity(m)\n    print(f\"  {m:4s}: IR {ir}, Raman {raman}\")\n"}, {"tier": "Foundations", "g": "Units", "title": "Units and Spectral Regions", "desc": "Spectroscopists mix units by tradition: nm for UV-vis, cm⁻¹ for IR, Hz/MHz for NMR and microwave, eV for X-ray, m/z for mass spec. Wavenumbers (cm⁻¹) are energy-proportional - the IR native unit; wavelength (nm) is not.\nRegions: far-IR/THz (lattice modes), mid-IR (functional groups), near-IR (overtones, process analysis), UV-vis (electronic), VUV/X-ray (core). Fluency means converting instantly and knowing each region's information content.", "how": "Convert: ν̄(cm⁻¹) = 10⁷/λ(nm); E(eV) = 1240/λ(nm). Choose units by region convention. Know the information per region: mid-IR = functional groups, NMR = connectivity, MS = mass/formula, X-ray = core/electronic structure.", "keys": ["nm: UV-vis; cm⁻¹: IR; Hz: NMR/microwave.", "Wavenumbers proportional to energy.", "Conversions: 10⁷/λ(nm) = cm⁻¹.", "Each region has characteristic information.", "THz: lattice modes; NIR: overtones."], "reqs": ["Region-appropriate units.", "Conversion factors.", "Information-content mapping."], "stds": ["IR in cm⁻¹; UV-vis in nm; NMR in Hz/ppm.", "Conversions shown in methods."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Banwell CN, McCash EM. Fundamentals of Molecular Spectroscopy. 4th ed. McGraw-Hill; 1994."], "demo": "#!/usr/bin/env python3\n\"\"\"Region unit conversions.\"\"\"\ndef nm_to_wn(nm): return 1e7/nm\nfor nm in (200, 500, 1000, 5000):\n    print(f\"  {nm:5d} nm = {nm_to_wn(nm):8.0f} cm⁻¹\")\n"}, {"tier": "Foundations", "g": "Safety", "title": "Laser Safety and Light-Source Hazards", "desc": "Lasers are classified 1 to 4: Class 1 (safe), 2 (blink reflex protects, visible low power), 3R/3B (eye hazard), 4 (burns skin, ignites - the research workhorse). Damage is wavelength-dependent: visible/NIR burns the retina (lens focuses it), UV/IR burns cornea and skin.\nControls: interlocks, beam blocks, eyewear matched to wavelength and OD, no reflective jewelry, high-voltage respect for lamp supplies. UV sources (deuterium, mercury) burn eyes and skin - never look at the arc; X-ray sources need shielding and dosimetry.", "how": "Classify every laser; implement controls per class (SOPs, eyewear, interlocks for 3B/4). Match eyewear OD and wavelength to the laser. Enclose beams where possible; use beam blocks during alignment at low power. Train and document - laser safety is administrative as well as physical.", "keys": ["Classes 1-4: increasing hazard.", "Retina at risk for visible/NIR; cornea for UV/IR.", "Eyewear matched to wavelength and OD.", "Interlocks and beam blocks for 3B/4.", "UV arcs and X-rays need their own controls."], "reqs": ["Laser classification.", "OD-rated eyewear per wavelength.", "Written SOPs and training."], "stds": ["ANSI Z136.1 laser safety standard.", "Eyewear OD marked per wavelength."], "cites": ["ANSI Z136.1. Safe Use of Lasers. Laser Institute of America.", "Sliney DH, Wolbarsht ML. Safety with Lasers. Plenum; 1980."], "demo": "#!/usr/bin/env python3\n\"\"\"Laser class controls lookup.\"\"\"\ncontrols = {\"Class 1\": \"none\", \"Class 2\": \"no staring\", \"Class 3B\": \"eyewear + SOP\", \"Class 4\": \"interlocks + eyewear + SOP + training\"}\nfor cls, ctl in controls.items():\n    print(f\"  {cls:8s}: {ctl}\")\n"}, {"tier": "Compounded", "g": "Electronic", "title": "UV-Visible Spectroscopy", "desc": "UV-vis probes electronic transitions: π→π* (conjugated systems, intense), n→π* (carbonyls, weak). Conjugation shifts absorption red - the particle-in-a-box in action: ethene 165 nm, butadiene 217 nm, β-carotene 450 nm. Color is selective absorption of visible light.\nWoodward-Fieser rules predict diene λmax from structure (base + substituent increments) - a pencil-and-paper triumph. Applications: conjugation analysis, kinetics (stopped-flow), protein quantitation (280 nm), nanoparticle plasmons.", "how": "Scan 190-800 nm; assign bands by intensity (ε > 10⁴: π→π*; ε < 100: n→π*). Predict diene λmax with Woodward-Fieser increments. Quantitate at λmax via Beer-Lambert; use diode arrays for kinetics and peak-purity. Choose solvents transparent at working wavelengths.", "keys": ["π→π* intense; n→π* weak.", "Conjugation shifts λmax to the red.", "Woodward-Fieser predicts diene absorption.", "Color = selective visible absorption.", "Solvent must be transparent at λ."], "reqs": ["Full spectrum, not single λ.", "Solvent cutoff respected.", "Band assignment by intensity."], "stds": ["λmax in nm with solvent.", "ε in M⁻¹cm⁻¹."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Woodward RB. J Am Chem Soc 1941;63:1123-1126."], "demo": "#!/usr/bin/env python3\n\"\"\"Woodward-Fieser: base diene + increments.\"\"\"\nbase = 217  # heteroannular diene\nincrements = {\"alkyl\": 5, \"exocyclic\": 5, \"extra conjugation\": 30}\ntotal = base + sum(increments.values())\nprint(f\"  predicted λmax: {total} nm\")\n"}, {"tier": "Compounded", "g": "Vibrational", "title": "Infrared Spectroscopy and Vibrations", "desc": "IR probes molecular vibrations: each bond is a spring (Hooke's law, ν̄ ∝ √(k/μ)) - O-H ~3600 cm⁻¹, C=O ~1715 cm⁻¹, C-H ~2900 cm⁻¹. The functional-group region (4000-1500) identifies groups; the fingerprint (1500-400) identifies the molecule.\nFTIR multiplexes via Michelson interferometry (Fellgett + Jacquinot advantages); ATR samples neat liquids and solids without preparation. Group frequencies are transferable - the analyst's lookup table for structure.", "how": "Assign group frequencies first (O-H, N-H, C=O, C≡C/C≡N), then fingerprint-match against libraries. Use ATR for neat samples; transmission for solutions (solvent windows matter). Confirm with complementary Raman (mutual exclusion) or MS/NMR.", "keys": ["Bond as spring: ν̄ proportional to sqrt(k/μ).", "Group region identifies; fingerprint confirms.", "FTIR: multiplex advantage.", "ATR: no-prep sampling.", "Group frequencies are transferable."], "reqs": ["4000-400 cm⁻¹ range.", "Sample prep matched (ATR/transmission).", "Library for fingerprint matching."], "stds": ["Wavenumbers in cm⁻¹.", "Band intensities (s/m/w)."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Griffiths PR, de Haseth JA. FTIR Spectrometry. 2nd ed. Wiley; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Group-frequency lookup.\"\"\"\ngroups = {\"O-H\": 3600, \"C-H\": 2900, \"C=O\": 1715, \"C=C\": 1650, \"C-O\": 1100}\nfor g, wn in sorted(groups.items(), key=lambda x: -x[1]):\n    print(f\"  {g:5s}: ~{wn} cm⁻¹\")\n"}, {"tier": "Compounded", "g": "Vibrational", "title": "Raman Spectroscopy", "desc": "Raman scatters photons inelastically: the shift equals vibrational energies. Selection rule differs from IR (polarizability change) - symmetric stretches strong in Raman, antisymmetric in IR; water is a weak Raman scatterer, making aqueous samples easy.\nLasers (785 nm common) excite; fluorescence can swamp signal (shift excitation or use SERS). Applications: polymorph ID, carbon materials (D/G bands), art forensics, process monitoring - non-destructive, through glass and water.", "how": "Choose excitation to dodge fluorescence (785/1064 nm for colored samples). Use Raman where IR struggles (aqueous, symmetric modes) and vice versa. Enhance with SERS (nanoparticle substrates, 10⁶×). Assign with group frequencies; confirm mutual exclusion in centrosymmetric molecules.", "keys": ["Inelastic scattering; shift = vibration.", "Polarizability rule complements IR.", "Water-friendly; fluorescence is the enemy.", "SERS enhances 10⁶×.", "Non-destructive, through containers."], "reqs": ["Excitation wavelength choice.", "Fluorescence assessment.", "Calibration (wavenumber standard)."], "stds": ["Shifts in cm⁻¹ from excitation.", "Laser λ and power stated."], "cites": ["Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017.", "Smith E, Dent G. Modern Raman Spectroscopy. 2nd ed. Wiley; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Raman shift from excitation and scattered λ.\"\"\"\ndef shift_cm1(ex_nm, sc_nm):\n    return 1e7/ex_nm - 1e7/sc_nm\nprint(f\"  785 nm -> 860 nm: {shift_cm1(785, 860):.0f} cm⁻¹\")\n"}, {"tier": "Compounded", "g": "Electronic", "title": "Fluorescence and Phosphorescence", "desc": "Fluorescence: singlet emission, nanoseconds, same multiplicity as ground state - excitation and emission spectra mirror (Kasha). Phosphorescence: triplet emission, milliseconds to seconds, quenched by O2 - the glow-in-the-dark mechanism.\nQuantum yield and lifetime report environment: quenching assays (Stern-Volmer), FRET distance rulers (1-10 nm, E ∝ 1/r⁶), fluorescent probes (GFP revolutionized biology - Nobel 2008). Sensitivity beats absorption 1000× - single molecules are routine.", "how": "Measure excitation and emission spectra; determine quantum yield vs standards. Use Stern-Volmer plots for quenching analysis. Apply FRET for nanometer distances (R₀ calibrated). Deoxygenate for phosphorescence; choose probes for photostability.", "keys": ["Fluorescence: singlet, ns; phosphorescence: triplet, slow.", "Kasha: emission from lowest excited state.", "FRET: 1-10 nm distance ruler.", "1000× more sensitive than absorption.", "GFP: Nobel 2008 imaging revolution."], "reqs": ["Excitation/emission spectra.", "Quantum-yield standard.", "O2 control for triplets."], "stds": ["Quantum yields dimensionless.", "Lifetimes in ns/µs/ms."], "cites": ["Lakowicz JR. Principles of Fluorescence Spectroscopy. 3rd ed. Springer; 2006.", "Shimomura O et al. (GFP Nobel 2008)."], "demo": "#!/usr/bin/env python3\n\"\"\"Stern-Volmer quenching plot.\"\"\"\ndef F0_F(Ksv, Q):\n    return 1 + Ksv*Q\nfor Q in (0, 0.01, 0.05, 0.1):\n    print(f\"  [Q]={Q:.2f} M: F0/F = {F0_F(50, Q):.2f}\")\n"}, {"tier": "Compounded", "g": "Atomic", "title": "Atomic Absorption Spectroscopy", "desc": "AAS atomizes (flame/air-acetylene 2300 °C; graphite furnace for ppb) and measures absorption from element-specific hollow-cathode lamps: each element needs its lamp, each analysis is single-element. Beer-Lambert quantifies: A ∝ concentration.\nBackground correction (deuterium, Zeeman) subtracts molecular absorption. Interferences: ionization (add K/La suppressant), refractory oxides (hotter N2O flame). Still the workhorse for metals in water, soil, and blood at ppm-ppb.", "how": "Choose flame (ppm, fast) or furnace (ppb, slow). Optimize burner height and fuel/oxidant. Use background correction; matrix-match standards. Validate with CRMs - contamination dominates error at trace levels.", "keys": ["Hollow-cathode lamp per element.", "Flame: ppm; furnace: ppb.", "Background correction essential.", "Ionization/refractory interferences managed.", "Workhorse for metals in water/soil/blood."], "reqs": ["Element-specific lamp.", "Atomizer matched to level.", "Background correction on."], "stds": ["Detection limits per element/method.", "CRM validation."], "cites": ["Welz B, Sperling M. Atomic Absorption Spectrometry. 3rd ed. Wiley-VCH; 1999.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"AAS calibration and unknown readout.\"\"\"\nstds = [(0, 0.01), (1, 0.12), (2, 0.23), (5, 0.56)]\nxs = [s[0] for s in stds]; ys = [s[1] for s in stds]\nn = len(xs)\nslope = (n*sum(a*b for a,b in zip(xs,ys))-sum(xs)*sum(ys))/(n*sum(a*a for a in xs)-sum(xs)**2)\nprint(f\"  slope {slope:.3f} A/ppm; A=0.34 -> {0.34/slope:.2f} ppm\")\n"}, {"tier": "Compounded", "g": "Atomic", "title": "Atomic Emission and ICP", "desc": "AES measures emission from excited atoms: flame photometry (Na/K in clinical labs) to ICP-OES (argon plasma 8000 K, multi-element ppb). The plasma's heat atomizes and excites nearly everything - 70+ elements in minutes.\nICP-MS adds mass detection: ppt levels, isotope ratios. Interferences (polyatomic overlaps: ⁴⁰Ar¹⁶O on ⁵⁶Fe) yield to collision/reaction cells and high resolution. Environmental and geological labs run on ICP.", "how": "Choose ICP-OES (ppb, robust, cheaper) vs ICP-MS (ppt, isotopes). Select interference-free lines/isotopes; use internal standards (Y, In) for drift. Digest completely - undissolved particles bias. Run blanks relentlessly.", "keys": ["ICP: 8000 K argon plasma atomizes all.", "ICP-OES: multi-element ppb; ICP-MS: ppt + isotopes.", "Polyatomic interferences managed by cells/resolution.", "Internal standards correct drift.", "Complete digestion required."], "reqs": ["Plasma conditions optimized.", "Interference-free lines/isotopes.", "Internal standard."], "stds": ["LOD per element in ppb/ppt.", "Isotope monitored stated."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Thomas R. Practical Guide to ICP-MS. 3rd ed. CRC; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Plasma temperature vs atomization.\"\"\"\nprint(\"  flame 2300 C: alkalis easy, refractories poor\")\nprint(\"  ICP 8000 K: atomizes nearly everything\")\n"}, {"tier": "Compounded", "g": "Magnetic", "title": "NMR: Principles", "desc": "NMR flips nuclear spins (¹H, ¹³C, ¹⁹F, ³¹P) in a magnetic field: resonance frequency ω = γB₀ - proportional to field (400 MHz ¹H at 9.4 T). Superconducting magnets, shimmed to ppb homogeneity, make it work.\nChemical shift (ppm, field-independent) reports electronic environment; spin-spin coupling (Hz, field-independent) reports neighbors (n+1 rule). Relaxation (T1, T2) reports dynamics. FT-NMR multiplexes: pulse, record FID, Fourier transform.", "how": "Lock and shim on deuterated solvent; reference (TMS 0 ppm). Read chemical shifts for environment, integrals for count, multiplicity for neighbors. Set relaxation delays (≥5T1) for quantitation. Choose nucleus: ¹H routine, ¹³C skeleton, ¹⁹F/³¹P heteroatoms.", "keys": ["ω = γB₀: frequency proportional to field.", "Chemical shift (ppm): environment.", "Coupling (Hz): neighbors (n+1 rule).", "FT: pulse, FID, transform.", "Superconducting magnets to ppb homogeneity."], "reqs": ["Deuterated solvent, lock, shim.", "Reference standard.", "Relaxation delay for quantitation."], "stds": ["Shifts in ppm; couplings in Hz.", "Field strength in MHz (¹H)."], "cites": ["Claridge TDW. High-Resolution NMR Techniques. 3rd ed. Elsevier; 2016.", "Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"n+1 rule: multiplicity from neighbors.\"\"\"\ndef multiplicity(n_neighbors):\n    return n_neighbors + 1\nfor n in (0, 1, 2, 3):\n    print(f\"  {n} neighbors -> {multiplicity(n)} peaks\")\n"}, {"tier": "Compounded", "g": "Magnetic", "title": "NMR: Chemical Shift and Coupling", "desc": "Chemical shift maps structure: ¹H 0-12 ppm (alkane ~1, alkene ~5-6, aromatic ~7, aldehyde ~9-10); ¹³C 0-220 ppm (carbonyl ~170-210). Electronegative neighbors deshield (downfield); ring currents shield/deshield anisotropically.\nCoupling constants encode geometry: ³J_HH ~7 Hz free rotation, Karplus (³J vs dihedral angle) for conformation, ¹J_CH ~125-250 Hz for hybridization (sp³ 125, sp² 160, sp 250). 2D experiments (COSY, HSQC, HMBC) map full connectivity.", "how": "Assign shifts by region and integration; confirm neighbors by multiplicity. Use J values for stereochemistry (Karplus: large ³J = anti). Run DEPT/HSQC for C-H mapping, HMBC for long-range C-H connections. Predict with increment rules or software.", "keys": ["¹H 0-12 ppm; ¹³C 0-220 ppm: the maps.", "Deshielding moves downfield.", "Karplus: ³J encodes dihedral angle.", "¹J_CH reports hybridization.", "2D NMR maps full connectivity."], "reqs": ["Assigned 1D spectra.", "J values measured.", "2D for complex structures."], "stds": ["δ in ppm; J in Hz.", "Solvent and reference stated."], "cites": ["Claridge TDW. High-Resolution NMR Techniques. 3rd ed. Elsevier; 2016.", "Karplus M. J Chem Phys 1959;30:11-15."], "demo": "#!/usr/bin/env python3\n\"\"\"Karplus curve: ³J vs dihedral angle (toy).\"\"\"\nimport math\ndef karplus(phi_deg):\n    p = math.radians(phi_deg)\n    return 7 - math.cos(p) + 5*math.cos(2*p)\nfor phi in (0, 60, 90, 180):\n    print(f\"  φ={phi:3d}°: ³J ≈ {karplus(phi):.1f} Hz\")\n"}, {"tier": "Compounded", "g": "Mass", "title": "Mass Spectrometry: Ionization", "desc": "Ionization makes gas-phase ions: EI (70 eV, hard - fragments, library-searchable, GC-MS), CI (softer, molecular ion), ESI (solution to gas, multiply charged - proteins), MALDI (laser + matrix, polymers/proteins), APCI/APPI (LC small molecules).\nHard ionization fragments (structure); soft preserves the molecular ion (mass). Adducts ([M+H]⁺, [M+Na]⁺, [M-H]⁻) are the ESI reality - read them correctly. Charge states (ESI: [M+nH]ⁿ⁺) extend mass range to megadaltons.", "how": "Match ionization to sample: volatile → EI; polar/LC → ESI/APCI; large biomolecules → ESI/MALDI. Identify adducts before assigning mass (Na⁺ +22, K⁺ +38). Deconvolute charge states for proteins. Calibrate mass axis; check with standards.", "keys": ["EI hard (fragments); ESI soft (molecular ion).", "Adducts: [M+H]⁺, [M+Na]⁺ - read carefully.", "Multiply charged ions extend mass range.", "MALDI: polymers/proteins; APCI: LC small molecules.", "Ionization matched to sample."], "reqs": ["Ionization method stated.", "Adduct identification.", "Mass calibration."], "stds": ["m/z with adduct/charge.", "Mass accuracy in ppm (HRMS)."], "cites": ["McLafferty FW, Turecek F. Interpretation of Mass Spectra. 4th ed. University Science; 1993.", "Gross JH. Mass Spectrometry. 3rd ed. Springer; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Adduct masses for M = 500.\"\"\"\nM = 500.0\nfor name, delta in [(\"[M+H]+\", 1.007), (\"[M+Na]+\", 22.990), (\"[M+K]+\", 38.964), (\"[M-H]-\", -1.007)]:\n    print(f\"  {name:8s}: m/z {M+delta:.3f}\")\n"}, {"tier": "Compounded", "g": "Mass", "title": "Mass Spec: Fragmentation and Interpretation", "desc": "EI fragments by predictable cleavages: alpha-cleavage (next to heteroatoms), McLafferty rearrangement (gamma-H transfer, even-electron ions), benzylic/allylic cleavage (stable cations). The nitrogen rule (odd nominal mass = odd N) and rings-plus-pi-bonds constrain formulas.\nIsotope patterns fingerprint halogens (Cl 3:1, Br 1:1) and count carbons (¹³C M+1 ~1.1% per C). High-res exact mass → elemental composition; MS/MS → structure. Interpretation is pattern recognition trained on mechanism.", "how": "Find the molecular ion (highest m/z, check nitrogen rule, isotope fit). List neutral losses (18 H₂O, 28 CO/C₂H₄, 44 CO₂). Assign cleavages by mechanism; use isotope patterns for formula. Confirm with HRMS exact mass (< 5 ppm).", "keys": ["Alpha-cleavage, McLafferty: the core mechanisms.", "Nitrogen rule constrains formulas.", "Isotope patterns count halogens/carbons.", "Neutral losses fingerprint groups.", "HRMS confirms composition."], "reqs": ["Molecular-ion assignment.", "Isotope-pattern match.", "HRMS confirmation."], "stds": ["Exact mass < 5 ppm.", "Losses in Da."], "cites": ["McLafferty FW, Turecek F. Interpretation of Mass Spectra. 4th ed. University Science; 1993.", "Gross JH. Mass Spectrometry. 3rd ed. Springer; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Nitrogen rule check.\"\"\"\ndef nitrogen_rule(mz):\n    return \"odd N (or odd H+odd N)\" if mz % 2 == 1 else \"even N\"\nfor mz in (100, 101, 150):\n    print(f\"  M+• {mz}: {nitrogen_rule(mz)}\")\n"}, {"tier": "Compounded", "g": "X-ray", "title": "X-ray Spectroscopy: Diffraction and Fluorescence", "desc": "XRD: crystals diffract X-rays (Bragg's law, nλ = 2d sinθ) - powder patterns fingerprint phases, single-crystal solves structures (the definitive structure proof). XRF: X-rays eject core electrons; emitted fluorescence identifies elements (Na-U) - non-destructive elemental analysis.\nXAS (XANES/EXAFS) probes oxidation state and local structure at synchrotrons. X-ray crystallography solved DNA, proteins (Nobel-rich), and every drug polymorph - the ultimate structural method.", "how": "Collect powder patterns; match to databases (PDF) for phase ID. Solve single crystals: collect, solve phases (direct methods), refine (R < 5% good). Use XRF for bulk elemental composition (matrix-matched standards). Reserve synchrotron XAS for oxidation-state questions.", "keys": ["Bragg: nλ = 2d sinθ.", "Powder XRD fingerprints phases.", "Single-crystal XRD is definitive structure proof.", "XRF: non-destructive elemental analysis.", "XAS: oxidation state + local structure."], "reqs": ["Crystalline sample (XRD).", "Wavelength known.", "Database for phase matching."], "stds": ["2θ in degrees; d in Å.", "R factors for refinements."], "cites": ["Cullity BD, Stock SR. Elements of X-Ray Diffraction. 3rd ed. Prentice Hall; 2001.", "Bragg WH, Bragg WL. Proc R Soc 1913;88:428-438."], "demo": "#!/usr/bin/env python3\n\"\"\"Bragg angle for d = 2 Å, Cu Kα.\"\"\"\nimport math\nlam = 1.5418\nd = 2.0\ntheta = math.degrees(math.asin(lam/(2*d)))\nprint(f\"  2θ = {2*theta:.2f}°\")\n"}, {"tier": "Compounded", "g": "Rotational", "title": "Microwave and Rotational Spectroscopy", "desc": "Microwave spectroscopy (GHz) probes molecular rotation: line spacing = 2B gives the moment of inertia → bond lengths to 0.001 Å - the most precise structures for small molecules. Only polar molecules absorb (dipole selection rule).\nApplications: atmospheric monitoring (O3, H2O lines), astrochemistry (interstellar molecules identified by rotational fingerprints - 200+ species), and structure determination. Stark modulation distinguishes real lines from noise.", "how": "Record pure rotational spectra of gas-phase polars; fit line spacing to B → moments of inertia → geometry. Use isotopic substitution (Kraitchman) for atom positions. Match interstellar lines to lab frequencies for astrochemical ID.", "keys": ["Spacing 2B → bond lengths (0.001 Å).", "Only polar molecules absorb.", "Most precise small-molecule structures.", "Astrochemistry's identification tool.", "Atmospheric trace-gas monitoring."], "reqs": ["Gas-phase polar sample.", "GHz frequency calibration.", "Isotopic data for full geometry."], "stds": ["Frequencies in MHz/GHz.", "B in MHz; lengths in Å."], "cites": ["Banwell CN, McCash EM. Fundamentals of Molecular Spectroscopy. 4th ed. McGraw-Hill; 1994.", "Townes CH, Schawlow AL. Microwave Spectroscopy. Dover; 1975."], "demo": "#!/usr/bin/env python3\n\"\"\"Rotational constant to bond length (diatomic, toy).\"\"\"\nimport math\ndef bond_length_pm(B_MHz, mu_amu):\n    # B = h/(8π²Ic); simplified scale\n    return (16.8576/(B_MHz*mu_amu*1e-4))**0.5*100\nprint(f\"  HCl B=312989 MHz: r ≈ {bond_length_pm(312989, 0.97):.1f} pm (ref 127.5)\")\n"}, {"tier": "Advanced", "g": "NMR", "title": "2D NMR Techniques", "desc": "2D NMR spreads spectra into two frequency dimensions: COSY correlates coupled protons (who neighbors whom), HSQC maps ¹H-¹³C one-bond pairs, HMBC reaches 2-3 bonds (quaternary carbons appear), NOESY maps through-space proximity (< 5 Å) - stereochemistry and conformation.\nTogether they solve structures no 1D spectrum can: natural products, proteins (backbone assignment), and mixtures. Acquisition is multiplexed (t1 increments); processing needs apodization and careful phasing in both dimensions.", "how": "Run COSY for H-H networks, HSQC for C-H pairs, HMBC for long-range links to quaternaries, NOESY for spatial contacts. Walk the correlations to assemble the skeleton; use NOEs for relative stereochemistry. Set t1 increments for needed F1 resolution.", "keys": ["COSY: H-H coupling; HSQC: C-H pairs.", "HMBC: long-range, finds quaternaries.", "NOESY: through-space (< 5 Å).", "Solves natural products and proteins.", "Two dimensions need careful processing."], "reqs": ["Assigned 1D spectra first.", "Adequate concentration (2D is insensitive).", "t1 resolution planned."], "stds": ["Mixing times stated (NOESY).", "F1/F2 spectral widths reported."], "cites": ["Claridge TDW. High-Resolution NMR Techniques. 3rd ed. Elsevier; 2016.", "Ernst RR et al. Principles of NMR in One and Two Dimensions. Oxford; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"2D experiment picker.\"\"\"\nqs = {\"H-H neighbors\": \"COSY\", \"C-H pairs\": \"HSQC\", \"quaternary carbons\": \"HMBC\", \"spatial contacts\": \"NOESY\"}\nfor q, exp in qs.items():\n    print(f\"  {q:18s} -> {exp}\")\n"}, {"tier": "Advanced", "g": "Vibrational", "title": "FTIR and Interferometry", "desc": "The Michelson interferometer splits light, recombines with path difference δ: the interferogram I(δ) Fourier-transforms to the spectrum - all wavelengths measured simultaneously (Fellgett) through one aperture (Jacquinot). HeNe laser referencing gives 0.01 cm⁻¹ wavenumber accuracy (Connes).\nAdvantages over dispersive: speed, throughput, precision - FTIR conquered IR by 1980. Step-scan adds time resolution (µs); synchrotron sources add brightness for microscopy.", "how": "Set resolution to the problem (4 cm⁻¹ routine, 0.5 for gases); more scans for S/N (√N). Apodize to control ringing; phase-correct (Mertz). Use ATR for surfaces/neat samples, transmission for quantitation, microscopy for mapping.", "keys": ["Interferogram FT → spectrum.", "Fellgett (multiplex) + Jacquinot (throughput).", "HeNe laser: 0.01 cm⁻¹ accuracy.", "S/N improves as √N scans.", "ATR, transmission, microscopy: three modes."], "reqs": ["Resolution matched to need.", "Apodization/phase correction.", "Background (air) spectrum."], "stds": ["Resolution in cm⁻¹ stated.", "Scans co-added reported."], "cites": ["Griffiths PR, de Haseth JA. FTIR Spectrometry. 2nd ed. Wiley; 2007.", "Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"FTIR S/N vs scans.\"\"\"\ndef sn(scans):\n    return scans**0.5\nfor n in (1, 16, 64, 256):\n    print(f\"  {n:3d} scans: relative S/N {sn(n):.0f}\")\n"}, {"tier": "Advanced", "g": "Lasers", "title": "Laser Spectroscopy", "desc": "Lasers bring coherence, intensity, and narrow linewidths: saturation spectroscopy beats Doppler broadening (Lamb dips), multiphoton ionization counts single atoms, cavity ring-down measures absorbances of 10⁻⁸ (trace gases, breath analysis).\nFrequency combs (Hänsch/Hall, Nobel 2005) are rulers for light - every tooth a precise frequency, enabling optical clocks (10⁻¹⁸) and exoplanet spectrographs. Tunable lasers (dye, Ti:sapphire, OPO) scan any wavelength.", "how": "Choose narrow-linewidth sources for Doppler-free work; combs for absolute frequency. Build cavities for ring-down (high-reflectivity mirrors, fast detectors). Tune OPOs across regions; calibrate with known lines or the comb itself.", "keys": ["Coherence + intensity + narrow lines.", "Doppler-free via saturation (Lamb dips).", "Cavity ring-down: 10⁻⁸ absorbance.", "Frequency combs: rulers for light (Nobel 2005).", "Tunable sources scan any wavelength."], "reqs": ["Linewidth vs Doppler width.", "Frequency calibration.", "Cavity finesse for ring-down."], "stds": ["Linewidths in Hz/kHz.", "Comb repetition rates stated."], "cites": ["Demtröder W. Laser Spectroscopy. 5th ed. Springer; 2014.", "Hall JL, Hänsch TW. (Nobel 2005)."], "demo": "#!/usr/bin/env python3\n\"\"\"Cavity ring-down: effective path length.\"\"\"\ndef path_km(L_m, R):\n    return L_m/(1-R)/1000\nprint(f\"  1 m cavity, R=0.99999: {path_km(1, 0.99999):.0f} km effective path\")\n"}, {"tier": "Advanced", "g": "Time-resolved", "title": "Time-Resolved Spectroscopy", "desc": "Pump-probe watches chemistry happen: a pump pulse initiates, a delayed probe snapshots - femtoseconds (bond breaking, Zewail Nobel 1999) to seconds (protein folding). Transient absorption maps excited states; time-resolved IR/Raman watches bonds; TCSPC counts fluorescence lifetimes.\nGlobal analysis disentangles overlapping kinetics; target analysis tests mechanisms. Applications: photosynthesis's first picoseconds, vision's 200 fs isomerization, charge separation in solar cells.", "how": "Set pump to initiate cleanly, probe to detect selectively; scan delays logarithmically. Keep excitation low (avoid multiphoton artifacts). Fit globally across wavelengths; validate with target models. Deoxygenate for triplet work.", "keys": ["Pump initiates; delayed probe snapshots.", "fs to s: full dynamic range.", "Global analysis disentangles kinetics.", "Photosynthesis, vision, solar cells.", "Low excitation avoids artifacts."], "reqs": ["Pump/probe wavelengths.", "Delay range and steps.", "Excitation density control."], "stds": ["Time constants with uncertainties.", "Instrument response stated."], "cites": ["Zewail AH. J Phys Chem A 2000;104:5660-5694.", "Berera R et al. Photosynth Res 2009;101:105-118."], "demo": "#!/usr/bin/env python3\n\"\"\"Log-spaced pump-probe delays.\"\"\"\ndelays = [10**e for e in range(-15, 1)]\nprint(f\"  {len(delays)} delays from {delays[0]:.0e} to {delays[-1]:.0e} s\")\n"}, {"tier": "Advanced", "g": "Surface", "title": "Surface Spectroscopies (XPS, AES)", "desc": "XPS (ESCA, Siegbahn Nobel 1981): X-rays eject core electrons; binding energy identifies elements and oxidation states (chemical shifts ~eV) - the surface analyst's workhorse, top 10 nm. AES uses Auger electrons (sharper, lighter elements, SEM-compatible).\nQuantitation needs sensitivity factors and homogeneous-depth assumptions; angle-resolved XPS profiles nanometers. Applications: catalysts, corrosion layers, semiconductor interfaces, cultural heritage - what the surface is made of and how it is bonded.", "how": "Calibrate binding energy (Au 4f, C 1s adventitious); fit peaks with Shirley backgrounds. Assign oxidation states from chemical shifts and satellites. Quantify with sensitivity factors; depth-profile with angle-resolved or sputtering (destructive).", "keys": ["XPS: elements + oxidation states, top 10 nm.", "AES: sharper, lighter elements.", "Chemical shifts ~eV encode bonding.", "Angle-resolved XPS depth-profiles.", "Surfaces: catalysts, corrosion, chips."], "reqs": ["Binding-energy calibration.", "Charge referencing.", "Sensitivity factors."], "stds": ["Binding energies in eV.", "Take-off angles stated."], "cites": ["Briggs D, Seah MP. Practical Surface Analysis. 2nd ed. Wiley; 1990.", "Siegbahn K. (Nobel 1981)."], "demo": "#!/usr/bin/env python3\n\"\"\"XPS chemical shift: Si oxidation states.\"\"\"\nshifts = {\"Si⁰\": 99.5, \"Si²⁺\": 101.5, \"Si⁴⁺ (SiO2)\": 103.5}\nfor state, be in shifts.items():\n    print(f\"  {state:12s}: Si 2p {be} eV\")\n"}, {"tier": "Advanced", "g": "Magnetic", "title": "Mössbauer Spectroscopy", "desc": "Mössbauer (Nobel 1961): recoil-free gamma emission/absorption gives neV-linewidth resonances - 10⁻¹² relative resolution. ⁵⁷Fe and ¹¹⁹Sn are the workhorses. Isomer shift reports s-electron density (oxidation/spin state); quadrupole splitting reports asymmetry; magnetic splitting reports internal fields.\nApplications: iron proteins, minerals, corrosion, catalysts - iron's oxidation and spin state unambiguously. The 14.4 keV ⁵⁷Fe transition is the classic; sources (⁵⁷Co) decay in place.", "how": "Use ⁵⁷Fe-enriched samples for sensitivity; calibrate velocity with α-Fe foil. Fit isomer shift (oxidation/spin), quadrupole splitting (symmetry), and magnetic hyperfine (ordering). Keep source and absorber at matched temperatures (recoil-free fraction).", "keys": ["neV linewidths: 10⁻¹² resolution.", "⁵⁷Fe and ¹¹⁹Sn workhorses.", "Isomer shift: oxidation/spin state.", "Quadrupole: symmetry; magnetic: ordering.", "Iron chemistry unambiguously."], "reqs": ["Mössbauer-active isotope.", "Velocity calibration.", "Temperature control."], "stds": ["Velocities in mm/s.", "Shifts vs α-Fe."], "cites": ["Mössbauer RL. Z Phys 1958;151:124-143.", "Gütlich P et al. Mössbauer Spectroscopy. Springer; 2011."], "demo": "#!/usr/bin/env python3\n\"\"\"⁵⁷Fe isomer-shift ranges (mm/s vs α-Fe).\"\"\"\nranges = {\"Fe⁰\": (-0.2, 0.0), \"Fe²⁺ HS\": (0.8, 1.4), \"Fe³⁺ HS\": (0.2, 0.5), \"Fe⁴⁺\": (-0.2, 0.2)}\nfor state, (lo, hi) in ranges.items():\n    print(f\"  {state:9s}: {lo:+.1f} to {hi:+.1f} mm/s\")\n"}, {"tier": "Advanced", "g": "Magnetic", "title": "EPR/ESR Spectroscopy", "desc": "EPR flips electron spins (GHz microwaves in a magnetic field): g-values report the radical's environment (free electron 2.0023; transition metals deviate by spin-orbit coupling), hyperfine splitting counts nearby nuclei (n+1 rule for electrons too).\nApplications: free radicals, triplet states, metalloproteins (FeS clusters, Cu²⁺), defects in solids, spin labels in biophysics (DEER measures nm distances). More sensitive than NMR (electron moment 658× larger) but only for paramagnets.", "how": "Choose frequency (X-band 9.5 GHz routine, Q/W for resolution); calibrate field with DPPH (g = 2.0036). Read g-anisotropy for metal sites; count hyperfine lines for ligand nuclei. Use spin traps (DMPO) for transient radicals; DEER for distance distributions.", "keys": ["Electron spins: GHz resonance.", "g-values report environment.", "Hyperfine counts nearby nuclei.", "658× more sensitive than NMR.", "Radicals, metals, defects, spin labels."], "reqs": ["Paramagnetic sample.", "Field/frequency calibration.", "Microwave power below saturation."], "stds": ["g-values dimensionless.", "Hyperfine in mT or MHz."], "cites": ["Weil JA, Bolton JR. Electron Paramagnetic Resonance. 2nd ed. Wiley; 2007.", "Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"EPR resonance field for g=2 at X-band.\"\"\"\ndef B_res(nu_GHz, g=2.0):\n    return nu_GHz*1e9*6.626e-34/(g*9.274e-24)\nprint(f\"  9.5 GHz, g=2.00: B = {B_res(9.5)*1000:.0f} mT\")\n"}, {"tier": "Advanced", "g": "Chiroptical", "title": "Circular Dichroism", "desc": "CD measures differential absorption of left/right circularly polarized light: chiral molecules (proteins, nucleic acids, chiral drugs) give Cotton effects at their chromophores. Far-UV CD (190-250 nm) reports protein secondary structure (α-helix: 208/222 nm minima; β-sheet: 218 nm).\nNear-UV/visible CD reports tertiary environment and ligand binding. Vibrational CD extends to IR. Applications: protein folding, enantiomeric excess, drug-protein binding - chirality in solution, fast and low-sample.", "how": "Measure far-UV for secondary structure; fit with reference datasets (DichroWeb). Use near-UV for tertiary changes and binding titrations. Determine ee from CD amplitude vs standards. Keep absorbance < 1 (dynode voltage check) for valid data.", "keys": ["ΔA = A_L - A_R: chirality's signal.", "Far-UV: secondary structure.", "α-helix: 208/222 nm minima.", "Near-UV: tertiary and binding.", "Fast, low-sample chirality probe."], "reqs": ["Chiral sample, transparent buffer.", "Absorbance < 1.", "Nitrogen purge below 200 nm."], "stds": ["Molar ellipticity in deg·cm²/dmol.", "Wavelengths in nm."], "cites": ["Kelly SM et al. Biochim Biophys Acta 2005;1751:119-139.", "Berova N et al. Circular Dichroism. 2nd ed. Wiley; 2000."], "demo": "#!/usr/bin/env python3\n\"\"\"Secondary-structure CD signatures (nm).\"\"\"\nsig = {\"alpha-helix\": [208, 222], \"beta-sheet\": [218], \"random coil\": [195]}\nfor ss, bands in sig.items():\n    print(f\"  {ss:12s}: minima near {bands} nm\")\n"}, {"tier": "Advanced", "g": "Hyphenated", "title": "Hyphenated Methods (GC-MS, LC-MS, CE-MS)", "desc": "Hyphenation couples separation to spectroscopy: GC-MS (EI libraries identify unknowns - forensics, environmental), LC-MS/MS (MRM quantitation at ppt - pharma, proteomics), GC-IR (isomer distinction), LC-NMR (structure of unknowns, insensitive but definitive).\nThe interface is the art: GC-MS needs vacuum-compatible flow; LC-MS needs atmospheric ionization (ESI/APCI); CE-MS needs sheath flow. Two-dimensional separations (GC×GC) multiply peak capacity for petroleum and metabolomics.", "how": "Match ionization to the separation (EI/GC, ESI/LC). Use retention + spectra for identification (library match + retention index). Quantify with internal standards (isotopic ideal). Deploy GC×GC for complex mixtures; LC-NMR for definitive unknown ID.", "keys": ["Separation + spectroscopy = identification power.", "GC-MS: libraries; LC-MS/MS: ppt quantitation.", "Interfaces bridge to vacuum.", "Retention + spectra confirm identity.", "GC×GC multiplies peak capacity."], "reqs": ["Compatible interface.", "Internal standard.", "Library/database access."], "stds": ["Retention indices with method.", "MS match factors reported."], "cites": ["McMaster MC. GC/MS: A Practical User Guide. 2nd ed. Wiley; 2007.", "Gross JH. Mass Spectrometry. 3rd ed. Springer; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Peak capacity: 1D vs GCxGC.\"\"\"\nprint(f\"  1D GC: ~500 peaks; GCxGC: {500*10} peaks (10x second dimension)\")\n"}, {"tier": "Advanced", "g": "Astro", "title": "Astronomical Spectroscopy", "desc": "Every element was first found in stars by its lines: Fraunhofer's solar lines (1814), helium named for the sun (1868) before Earth, redshift (Hubble 1929) revealing expansion. Spectroscopy is astronomy's primary instrument.\nTools: Doppler shifts (radial velocities, exoplanets), line widths (temperatures, turbulence), abundances (stellar metallicity), molecular rotational lines (interstellar clouds, ALMA). The 21-cm hydrogen line maps the galaxy; CMB spectroscopy probes the Big Bang.", "how": "Measure redshifts (z = Δλ/λ) for velocities/distances. Fit line profiles for temperature/turbulence. Derive abundances from equivalent widths with stellar models. Match rotational lines to lab frequencies for molecular ID; map with interferometers (ALMA).", "keys": ["Fraunhofer lines: the founding observation.", "Redshift reveals cosmic expansion.", "Doppler finds exoplanets.", "Rotational lines map interstellar molecules.", "21-cm line maps galactic hydrogen."], "reqs": ["Wavelength calibration (sky lines).", "Redshift correction.", "Lab line lists."], "stds": ["Redshift z dimensionless.", "Radial velocities in km/s."], "cites": ["Fraunhofer J. Denkschriften Akad München 1817;5:193-226.", "Hubble E. Proc Natl Acad Sci 1929;15:168-173."], "demo": "#!/usr/bin/env python3\n\"\"\"Redshift velocity (non-relativistic).\"\"\"\ndef v_kms(z):\n    return z*299792.458\nfor z in (0.001, 0.01, 0.1):\n    print(f\"  z={z}: v ≈ {v_kms(z):.0f} km/s\")\n"}, {"tier": "Advanced", "g": "Theory", "title": "Quantum Theory of Spectra", "desc": "Spectra are quantum transitions: Einstein coefficients (A spontaneous, B stimulated/absorption) give rates; transition dipole moments give intensities (allowed vs forbidden); Franck-Condon overlaps give vibronic band shapes.\nTime-dependent perturbation theory (Fermi's golden rule) predicts rates; selection rules fall out of matrix elements. Modern computation (TD-DFT, EOM-CCSD) predicts spectra before measurement - theory and spectroscopy converging after a century.", "how": "Compute transition dipoles for intensities; apply Fermi's golden rule for rates. Use Franck-Condon factors for vibronic structure. Predict with TD-DFT (benchmark functionals); assign experimental bands by computed energies and intensities.", "keys": ["Einstein A/B: transition rates.", "Transition dipoles give intensities.", "Franck-Condon shapes vibronic bands.", "Fermi's golden rule predicts rates.", "TD-DFT predicts spectra computationally."], "reqs": ["Wavefunctions of both states.", "Perturbation operator.", "Benchmark data."], "stds": ["Oscillator strengths dimensionless.", "Rates in s⁻¹."], "cites": ["Dirac PAM. Proc R Soc 1927;114:243-265.", "Atkins P, Friedman R. Molecular Quantum Mechanics. 5th ed. Oxford; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Fermi golden rule scaling.\"\"\"\nprint(\"  rate proportional to |<f|V|i>|² × density of states\")\nprint(\"  2x coupling -> 4x rate\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-SPECCS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-SPECCS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-spectroscopy-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('spectroscopy-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
